Fixes: 8d975c15c0cd ("ip6_tunnel: make sure to pull inner header in __ip6_tnl_rcv()")
Reported-by: syzbot+d4dda070f833dc5dc89a@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/netdev/695e88b2.050a0220.1c677c.036d.GAE@google.com/T/#u
Signed-off-by: Eric Dumazet <edumazet@google.com>
Link: https://patch.msgid.link/20260107163109.4188620-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The previous fix (commit 8d975c15c0cd) used `pskb_inet_may_pull()` in `__ip6_tnl_rcv()` to ensure the inner network header is pulled, but this function does not account for VLAN headers. When a VLAN-tagged packet arrives, the network header is positioned after the VLAN tag, and `pskb_inet_may_pull()` only checks if the network header's length is available without pulling the VLAN header first. This results in the network header not being fully present in the skb's linear data, leading to uninitialized memory reads when the code later accesses inner header fields (e.g., ECN bits) during decapsulation, causing the KMSAN uninit-value bug.

Here is the patch:

 static int __ip6_tnl_rcv(struct ip6_tnl *tunnel, struct sk_buff *skb,
 			 const struct tnl_ptk_info *tpi,
 			 struct metadata_dst *tun_dst,
 			 int (*dscp_ecn_decapsulate)(const struct ip6_tnl *t,
 						const struct ipv6hdr *ipv6h,
 						struct sk_buff *skb),
 			 bool log_ecn_err)
 {
 	const struct ipv6hdr *ipv6h;
 	int nh, err;

 	if (test_bit(IP_TUNNEL_CSUM_BIT, tunnel->parms.i_flags) !=
 	    test_bit(IP_TUNNEL_CSUM_BIT, tpi->flags)) {
 		DEV_STATS_INC(tunnel->dev, rx_crc_errors);
 		DEV_STATS_INC(tunnel->dev, rx_errors);
 		goto drop;
 	}

 	if (test_bit(IP_TUNNEL_SEQ_BIT, tunnel->parms.i_flags)) {
 		if (!test_bit(IP_TUNNEL_SEQ_BIT, tpi->flags) ||
 		    (tunnel->i_seqno &&
 		     (s32)(ntohl(tpi->seq) - tunnel->i_seqno) < 0)) {
 			DEV_STATS_INC(tunnel->dev, rx_fifo_errors);
 			DEV_STATS_INC(tunnel->dev, rx_errors);
 			goto drop;
 		}
 		tunnel->i_seqno = ntohl(tpi->seq) + 1;
 	}

 	skb->protocol = tpi->proto;

 	/* Warning: All skb pointers will be invalidated! */
 	if (tunnel->dev->type == ARPHRD_ETHER) {
 		if (!pskb_may_pull(skb, ETH_HLEN)) {
 			DEV_STATS_INC(tunnel->dev, rx_length_errors);
 			DEV_STATS_INC(tunnel->dev, rx_errors);
 			goto drop;
 		}

 		skb->protocol = eth_type_trans(skb, tunnel->dev);
 		skb_postpull_rcsum(skb, eth_hdr(skb), ETH_HLEN);
 	} else {
 		skb->dev = tunnel->dev;
 		skb_reset_mac_header(skb);
 	}

 	/* Save offset of outer header relative to skb->head,
 	 * because we are going to reset the network header to the inner header
 	 * and might change skb->head.
 	 */
 	nh = skb_network_header(skb) - skb->head;

 	skb_reset_network_header(skb);

-	if (!pskb_inet_may_pull(skb)) {
+	if (skb_vlan_inet_prepare(skb, true)) {
 		DEV_STATS_INC(tunnel->dev, rx_length_errors);
 		DEV_STATS_INC(tunnel->dev, rx_errors);
 		goto drop;
 	}

 	/* Get the outer header. */
 	ipv6h = (struct ipv6hdr *)(skb->head + nh);

 	memset(skb->cb, 0, sizeof(struct inet6_skb_parm));

 	__skb_tunnel_rx(skb, tunnel->dev, tunnel->net);

 	err = dscp_ecn_decapsulate(tunnel, ipv6h, skb);
 	if (unlikely(err)) {
 		if (log_ecn_err)
 			net_info_ratelimited("non-ECT from %pI6 with DS=%#x\n",
 					     &ipv6h->saddr,
 					     ipv6_get_dsfield(ipv6h));
 		if (err > 1) {
 			DEV_STATS_INC(tunnel->dev, rx_frame_errors);
 			DEV_STATS_INC(tunnel->dev, rx_errors);
 			goto drop;
 		}
 	}

 	dev_sw_netstats_rx_add(tunnel->dev, skb->len);

 	skb_scrub_packet(skb, !net_eq(tunnel->net, dev_net(tunnel->dev)));

 	if (tun_dst)
 		skb_dst_set(skb, (struct dst_entry *)tun_dst);

 	gro_cells_receive(&tunnel->gro_cells, skb);
 	return 0;

 drop:
 	if (tun_dst)
 		dst_release((struct dst_entry *)tun_dst);
 	kfree_skb(skb);
 	return 0;
 }



